# claude-deck kitten: pane operations that must run inside kitty, without stealing
# OS focus (peek), or that need kitty internals (tile, close with confirmation).
# Called by the daemon as: kitty @ kitten deck.py <command> [args...]
# Generated by claude-deck; edits are overwritten when the deck starts.
import json

from kittens.tui.handler import result_handler


def main(args: list[str]) -> None:
    pass


def _select(boss, w) -> None:
    """Make w the active pane of its tab and its tab the active tab, without asking
    the compositor for OS focus (raising is the daemon's job)."""
    tab = w.tabref()
    if tab is None:
        return
    tm = tab.tab_manager_ref()
    if tm is not None and tm.active_tab is not tab:
        tm.set_active_tab(tab)
    if tab.active_window is not w:
        tab.set_active_window(w)


def _active_window_of(boss):
    tm = boss.active_tab_manager
    if tm is None or tm.active_tab is None:
        return None
    return tm.active_tab.active_window


@result_handler(no_ui=True)
def handle_result(args: list[str], answer, target_window_id: int, boss):
    cmd, rest = (args[1], args[2:]) if len(args) > 1 else ('', [])
    win = lambda i: boss.window_id_map.get(int(i))

    if cmd == 'peek':
        w = win(rest[0])
        if w is None:
            return 'missing'
        if getattr(boss, '_claude_deck_peek', None) is None:
            prev = _active_window_of(boss)
            boss._claude_deck_peek = prev.id if prev else None
        _select(boss, w)
        return 'ok'

    if cmd == 'unpeek':
        prev = getattr(boss, '_claude_deck_peek', None)
        boss._claude_deck_peek = None
        w = win(prev) if prev else None
        if w is not None:
            _select(boss, w)
        return 'ok'

    if cmd == 'focus':
        boss._claude_deck_peek = None
        w = win(rest[0])
        if w is None:
            return 'missing'
        _select(boss, w)
        return 'ok'

    if cmd == 'tile':
        # Gather every session pane into the active tab, in a grid.
        ids = [int(x) for x in rest]
        tm = boss.active_tab_manager
        if tm is None or tm.active_tab is None:
            return 'none'
        target = tm.active_tab
        for i in ids:
            w = win(i)
            if w is not None and w.tabref() is not target:
                boss._move_window_to(window=w, target_tab_id=target.id)
        target.goto_layout('grid')
        return 'ok'

    if cmd == 'untile':
        tm = boss.active_tab_manager
        if tm is None or tm.active_tab is None:
            return 'none'
        tab = tm.active_tab
        ids = set(int(x) for x in rest)
        keep = tab.active_window
        for w in list(tab):
            if w is not keep and w.id in ids:
                boss._move_window_to(window=w, target_tab_id='new')
        tm.set_active_tab(tab)
        return 'ok'

    if cmd == 'close':
        w = win(rest[0])
        if w is None:
            return 'missing'
        working = len(rest) > 1 and rest[1] == 'working'
        if not working:
            boss.mark_window_for_close(w)
            return 'ok'

        def done(confirmed: bool, wid: int) -> None:
            x = boss.window_id_map.get(wid)
            if confirmed and x is not None:
                boss.mark_window_for_close(x)

        boss.confirm('Claude is still working in this pane.\nClose it anyway?', done, w.id, window=w, title='Close session')
        return 'ok'

    if cmd == 'layout':
        # The tab id that holds each window, so the daemon can save the workspace.
        out = {}
        for tm in boss.all_tab_managers:
            for t in tm:
                for w in t:
                    out[str(w.id)] = {'tab': t.id, 'os_window': tm.os_window_id, 'layout': t.current_layout.name}
        return json.dumps(out)

    return 'unknown'
